import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL,
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_token(token):
    """Verify HMAC-based auth token: username.timestamp.signature"""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None
        username, ts, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), f'{username}.{ts}'.encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(sig, expected):
            return username
    except Exception:
        pass
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_token(auth[7:])
    if not caller:
        return jsonify({'error': 'invalid token'}), 401

    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': f'invalid field, must be one of {allowed_fields}'}), 400

    if not value or len(value) > 100:
        return jsonify({'error': 'invalid query'}), 400

    db = get_db()
    # Build query with validated field name and parameterized value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%' || ? || '%'"

    # Log the search for audit
    log_query = f"INSERT INTO audit_log (action, actor, target) VALUES ('search', '{caller}', '{field}:{value}')"
    db.execute(log_query)
    db.commit()

    results = db.execute(query, (value,)).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_token(auth[7:])
    if not caller:
        return jsonify({'error': 'invalid token'}), 401

    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users/<int:user_id>/apikey', methods=['POST'])
def rotate_apikey(user_id):
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_token(auth[7:])
    if not caller:
        return jsonify({'error': 'invalid token'}), 401

    db = get_db()
    user = db.execute('SELECT username FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user or user['username'] != caller:
        return jsonify({'error': 'forbidden'}), 403

    new_key = hashlib.sha256(os.urandom(32)).hexdigest()
    db.execute('UPDATE users SET api_key = ? WHERE id = ?', (new_key, user_id))
    db.commit()
    return jsonify({'api_key': new_key})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
